// Build the SOP §7 team-wide welcome announcement. We don't have Teams API
// access yet — instead we email the generated message to the Onboarding Lead
// who pastes it into the Teams group chat. Inbound payload from Next.js:
//   { onboarderId, template:'group-chat-announce', event, context: {
//     full_name, first_name, onboarder_type ('contractor'|'intern'),
//     onboarder_type_label, role_title, team, direct_supervisor, start_date,
//     onboarding_lead
//   } }

const body = ($input.first().json.body ?? $input.first().json);
const ctx  = body.context || {};
const fullName         = ctx.full_name           || 'New Romega Team Member';
const firstName        = ctx.first_name          || fullName.split(' ')[0];
const typeLabel        = ctx.onboarder_type_label || (ctx.onboarder_type === 'intern' ? 'intern' : 'contractor');
const roleTitle        = ctx.role_title          || '';
const team             = ctx.team                || '';
const directSupervisor = ctx.direct_supervisor   || 'their Direct Supervisor';
const startDate        = ctx.start_date          || 'TBD';
const onboardingLead   = ctx.onboarding_lead     || 'Erich';

const roleLine = [roleTitle, team].filter(Boolean).join(' · ');

const announcement = `👋 Team, please welcome our newest ${typeLabel}, *${fullName}*${roleLine ? ` (${roleLine})` : ''}. They're starting on ${startDate}. ${directSupervisor} will be their direct supervisor. Welcome to Romega, ${firstName}! 🎉`;

const subject = `Paste-ready: announce ${fullName} in the team chat`;
const body_ = `Hi ${onboardingLead},

Here's the team-wide welcome message for ${fullName} — copy & paste into the Teams group chat when ready:

----- BEGIN MESSAGE -----
${announcement}
----- END MESSAGE -----

This was auto-generated from the onboarder record. If the role title or start date needs tweaking, edit the onboarder and regenerate.

— Onboarding bot`;

// Send to the Onboarding Lead. We pull their email from a future field on
// onboarders; for now we fall back to the lead-name based mailbox.
const toEmail = ctx.onboarding_lead_email || 'erich@romega-solutions.com';

return [{ json: { to: toEmail, subject, body: body_, announcement, onboarderId: body.onboarderId, template: 'group-chat-announce' } }];
